package com.ruskcoder.messages.games

import android.util.Base64
import kotlin.math.floor
import kotlin.random.Random

/**
 * GamePigeon's wire obfuscation — a deterministic character permutation, **not** encryption.
 *
 * Ported verbatim from OpenPigeon's `Cryption` so a payload this app produces is byte-identical to
 * one GamePigeon on iOS (or OpenPigeon on Android) produces for the same input. The permutation is
 * generated by a `drand48`-style PRNG seeded with `length * 0xef`; there is no key and no secret.
 * It exists only to match GamePigeon's format. Do not put anything sensitive through it.
 */
object Cryption {

    /** The `drand48` family, as Android's platform C library implements it. */
    private class Rand48(seed: Long = 0) {
        private var n: Long = seed

        fun srand(seed: Int) {
            n = (seed.toLong() shl 16) + 0x330e
        }

        private fun next(): Long {
            n = (0x5DEECE66DL * n + 0xB) and ((1L shl 48) - 1)
            return n
        }

        fun drand(): Double = next().toDouble() / (1L shl 48)
    }

    /** Reverse of [encrypt]: recover the original ordering of [string]. */
    fun decrypt(string: String): String {
        val rand = Rand48()
        rand.srand(string.length * 0xef)

        val offsets = ArrayList<Int>(string.length)
        var modifier = 0
        for (i in string.indices) {
            offsets.add(floor(rand.drand() * (modifier + string.length)).toInt())
            modifier--
        }

        var output = ""
        for ((i, offset) in offsets.asReversed().withIndex()) {
            val index = string.length - i - 1
            output = output.substring(0, offset) + string[index] + output.substring(offset)
        }
        return output
    }

    /** Permute [string] into the order GamePigeon expects on the wire. */
    fun encrypt(string: String): String {
        val rand = Rand48()
        rand.srand(string.length * 0xef)

        val result = StringBuilder(string.length)
        var remaining = string
        for (i in string.indices) {
            val idx = floor(rand.drand() * remaining.length).toInt()
            result.append(remaining[idx])
            remaining = remaining.substring(0, idx) + remaining.substring(idx + 1)
        }
        return result.toString()
    }

    /** A fresh random 12-byte id, base64 — GamePigeon's per-message `id`. */
    fun newId(): String =
        Base64.encodeToString(ByteArray(12).also { Random.nextBytes(it) }, Base64.NO_WRAP)
}
